  'app.ln3.8fcc33f5f280': 'Finder 在 Leopard 中加入 Cover Flow、Quick Look、重新设计的侧栏和局域网共享浏览。',
  'app.ln3.2901304ad2a8': 'Safari 是 Apple 的网页浏览器。Leopard 随附 Safari 3，并基于 WebKit 排版引擎。',
  'app.ln3.38c7ff950bcd': 'Dashboard 是 Mac OS X 的 Widget 层，可通过快捷键覆盖显示天气、计算器、时钟等小组件。',
  'app.ln3.7ffd2079caca': 'Quartz 是 macOS 的二维绘图与窗口合成技术；Quartz Extreme 使用图形硬件加速合成。',
  'app.ln3.c8468a159d79': 'Aqua 使用半透明材质、凝胶式控件、拉丝金属和连续动画建立 Mac OS X 的视觉语言。',
  'app.ln3.b072ea0a86d6': 'Spotlight 可搜索文件、邮件、联系人及应用，Leopard 中也能用于网络共享。',
  'app.ln3.e4a6fa224098': 'VoiceOver 是 Mac OS X 内建的屏幕阅读器，通过语音和盲文描述界面内容。',
  'app.ln3.71175ed133a7': 'Leopard Dock 使用反光的三维搁板，并加入 Stacks 文件夹堆栈。',
  'app.ln3.1de0b7b0d534': 'Finder 的“废纸篓”暂存已删除文件，可恢复项目或清倒以释放虚拟存储。',
  'app.ln3.bc14a0242b5d': '可在视频聊天中共享照片、演示文稿、影片和 Quick Look 文稿。',
  'app.ln3.e75720898bce': '“预览”可阅读 PDF 与图像，提供缩放、旋转、检查和注释工具。',
  'app.ln3.092ffe19a1b8': '网页无法接管另一台 Mac，但已保留完整的邀请和状态界面。',
  'app.ln3.ba21304fb20f': '屏幕边缘用于启动应用、切换窗口和存放项目的栏。',
  'app.ln3.64b2ec23a9d9': 'Mac OS X 的图形用户界面设计语言。',
  'app.ln3.b2c9b796c9a5': 'Mac OS X 的系统级元数据搜索功能。',
  'app.ln3.44beedc303bf': '群组中的名片会保留，并移到“朋友”群组。',
  'app.ln3.6025af86ea48': '你好！这是一段本地 iChat 会话。',
