  'app.ln8.6d6a17c66c6d': '本助理只在虚拟 Macintosh HD 中建立迁移结果；不会读取真实 Mac 的账户、密码或整块磁盘。',
  'app.ln8.38a74c866253': '此助理不会覆盖当前账户；旧账户会重新命名为“roll-old”，其个人文件会放在迁移结果文件夹中。',
  'app.ln8.bb58052af976': '传输完成前，当前账户与现有文件保持不变。发现同名账户或文件时，助理会先采用安全的重命名策略。',
  'app.ln8.639ae798be5e': '安全说明：模拟器从不读取或保存真实密码；解锁只影响此窗口的显示状态。',
  'app.ln8.e8dbf0bc17af': '如果从另一台 Mac 传输，请将两台电脑接入同一网络。',
  'app.ln8.7a29c6fe4c74': '大量信息可能需要较长时间；传输期间仍可在写入前停止。',
  'app.ln8.0e30c73c30c9': '点按下方按钮，从真实本机选择一个 .iso 文件。',
  'app.ln8.fbe8ac5f926f': '迁移时会保留创建日期、文件类型与原始来源信息。',
  'app.ln8.371b46daa7f1': '这是虚拟迁移会话验证码；不会要求真实账户密码。',
  'app.ln8.5582dd7bb806': '报告保存在“文稿”中，也已加入最近使用的文稿。',
  'app.ln8.ec20514db415': '请确认“文稿”文件夹仍然可用，然后返回并重试。',
  'app.ln8.58e76ecb0308': '网页会保留当前文件；仍建议先检查重要文稿',
